def chain_follow(chain):
    chain_dict = {}
    for a, b in chain:
        if a not in chain_dict:
            chain_dict[a] = []
        chain_dict[a].append(b)

    chain_dict = sorted(chain_dict.items())

    current = chain_dict[0]
    result = []

    while current:
        next_item = current[1][0]
        result.append(next_item)
        current = current[1]

    return ','.join(result)
```

